import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import{World}from'../world.js';import{roomFixtures,REALISM_ATLAS}from'../room-realism.js';import{findPath}from'../navigation.js';
const w=new World(JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url))));
test('occupied workstations have real collision, clear reachable approaches and valid atlas cells',()=>{let count=0;for(const s of w.data.scenes.filter(s=>s.household&&!s.originId))for(const o of s.household.furnishings.filter(o=>o.visual)){count++;assert.ok(Object.hasOwn(REALISM_ATLAS,o.visual));const b=o.footprint;assert.ok(b.w>=2&&(b.h>=2||o.visual==='pantry'&&b.h===1));if(b.h===1)for(let x=b.x;x<b.x+b.w;x++)assert.notEqual(s.household.floorBase[b.y-1]?.[x],'.','a shallow pantry is backed by the wall');for(let y=b.y;y<b.y+b.h;y++)for(let x=b.x;x<b.x+b.w;x++)assert.equal(s.floor[y][x],'#');assert.ok(findPath(s,s.arrive,o.xy,1).length||Math.hypot(s.arrive[0]-o.xy[0],s.arrive[1]-o.xy[1])<=1,s.key+':'+o.label);}assert.ok(count>=100);});
test('generic decorative planters and loose chests are restricted to appropriate rooms and retained stock',()=>{for(const s of w.data.scenes.filter(s=>s.household&&!s.originId)){const k=s.household.kind;for(const o of s.household.furnishings){if(o.furniture===17)assert.ok(['garden','home','nursery'].includes(k));if(o.furniture===12&&!o.supply)assert.ok(['cargo','store'].includes(k));}assert.ok(s.household.composition.realism===7);}});
test('room work determines the kit; food storage is not used as the medical cabinet',()=>{assert.ok(roomFixtures('clinic','clinic').some(x=>x.visual==='treatment'));assert.ok(!roomFixtures('clinic','clinic').some(x=>x.visual==='pantry'));assert.ok(roomFixtures('tailor','secret_15').some(x=>x.visual==='textiles'));assert.ok(roomFixtures('workshop','pottery_floor').some(x=>x.visual==='ceramics'));assert.ok(roomFixtures('cistern','flood_spillway').some(x=>x.visual==='pumping'));});
